package com.studio.ai;

import android.app.Activity;
import android.os.Bundle;
import android.content.Intent;
import android.content.SharedPreferences;
import android.database.Cursor;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.media.MediaMetadataRetriever;
import android.net.Uri;
import android.provider.OpenableColumns;
import android.view.Gravity;
import android.view.View;
import android.widget.*;
import org.json.JSONArray;
import org.json.JSONObject;
import java.text.SimpleDateFormat;
import java.util.*;

public class MainActivity extends Activity {
    private LinearLayout root, content;
    private SharedPreferences prefs;
    private String project="", style="";
    private Runnable backAction;
    private static final int PICK_VIDEO=2001;
    private final int BG=Color.rgb(9,11,15), CARD=Color.rgb(19,23,30), MUTED=Color.rgb(151,160,174), GREEN=Color.rgb(124,255,178);
    private final String[] styles={"إعلانات الشركات","تجمعيات أنمي","TikTok","YouTube","رعب","أكشن","عام"};

    @Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("studio",MODE_PRIVATE);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);home();}
    private int dp(float x){return Math.round(x*getResources().getDisplayMetrics().density);}
    private GradientDrawable bg(int c,float r){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(r));return d;}
    private TextView tx(String s,float z,int c,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);v.setTypeface(Typeface.create("sans",bold?Typeface.BOLD:Typeface.NORMAL));v.setGravity(Gravity.END|Gravity.CENTER_VERTICAL);v.setTextDirection(View.TEXT_DIRECTION_RTL);v.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);v.setLineSpacing(0,1.12f);return v;}
    private Button btn(String s){Button b=new Button(this);b.setText(s);b.setTextSize(16);b.setAllCaps(false);b.setTextColor(Color.rgb(5,20,13));b.setTypeface(null,Typeface.BOLD);b.setBackground(bg(GREEN,18));return b;}
    private void base(String title,String sub){ScrollView sc=new ScrollView(this);sc.setFillViewport(true);sc.setBackgroundColor(BG);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);root.setBackgroundColor(BG);sc.addView(root,new ScrollView.LayoutParams(-1,-2));setContentView(sc);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(dp(20),i.getSystemWindowInsetTop()+dp(14),dp(20),i.getSystemWindowInsetBottom()+dp(24));return i;});root.requestApplyInsets();TextView brand=tx("STUDIO  /  AI",12,GREEN,true);brand.setTextDirection(View.TEXT_DIRECTION_LTR);brand.setLetterSpacing(.16f);root.addView(brand);TextView t=tx(title,29,Color.WHITE,true);LinearLayout.LayoutParams tl=new LinearLayout.LayoutParams(-1,-2);tl.setMargins(0,dp(8),0,dp(4));root.addView(t,tl);TextView s=tx(sub,14,MUTED,false);LinearLayout.LayoutParams sl=new LinearLayout.LayoutParams(-1,-2);sl.setMargins(0,0,0,dp(22));root.addView(s,sl);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);root.addView(content);}
    private void back(String label,Runnable r){TextView b=tx("‹  "+label,15,GREEN,true);b.setPadding(0,dp(22),0,dp(18));root.addView(b);b.setOnClickListener(v->r.run());backAction=r;}

    private void home(){project="";style="";backAction=null;base("الاستوديو","مساحة عملك الخاصة للمونتاج والتعلّم من الأساليب.");Button add=btn("＋  إنشاء مشروع");content.addView(add,new LinearLayout.LayoutParams(-1,dp(58)));add.setOnClickListener(v->newProject());TextView h=tx("المشاريع الأخيرة",18,Color.WHITE,true);LinearLayout.LayoutParams hl=new LinearLayout.LayoutParams(-1,-2);hl.setMargins(0,dp(28),0,dp(12));content.addView(h,hl);Set<String> ps=prefs.getStringSet("projects",new LinkedHashSet<>());if(ps.isEmpty())content.addView(tx("لا توجد مشاريع بعد.",14,MUTED,false));else for(String p:ps){String[] x=p.split("\\|",2);card(x[0],x.length>1?x[1]:"عام",()->workspace(x[0],x.length>1?x[1]:"عام"));}}
    private void newProject(){base("مشروع جديد","اكتب اسم المشروع ثم اختر قسمه.");EditText e=new EditText(this);e.setHint("مثال: إعلان مطعم العميل");e.setHintTextColor(MUTED);e.setTextColor(Color.WHITE);e.setTextDirection(View.TEXT_DIRECTION_RTL);e.setGravity(Gravity.END|Gravity.CENTER_VERTICAL);e.setBackground(bg(CARD,18));e.setPadding(dp(18),0,dp(18),0);content.addView(e,new LinearLayout.LayoutParams(-1,dp(58)));Button n=btn("التالي  ←");LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(56));lp.setMargins(0,dp(18),0,0);content.addView(n,lp);n.setOnClickListener(v->{String name=e.getText().toString().trim();if(name.isEmpty()){e.setError("اكتب اسم المشروع");return;}chooseStyle(name);});back("رجوع للرئيسية",this::home);}
    private void chooseStyle(String name){base("اختر أسلوب المشروع","كل قسم مستقل بمواده وتحليلاته.");for(String s:styles)card(s,"",()->saveProject(name,s));back("رجوع للرئيسية",this::home);}
    private void saveProject(String name,String s){Set<String> p=new LinkedHashSet<>(prefs.getStringSet("projects",new LinkedHashSet<>()));p.add(name+"|"+s);prefs.edit().putStringSet("projects",p).apply();workspace(name,s);}
    private void card(String title,String sub,Runnable r){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setBackground(bg(CARD,18));c.setPadding(dp(18),dp(13),dp(18),dp(13));c.setMinimumHeight(dp(66));c.addView(tx(title,17,Color.WHITE,true));if(!sub.isEmpty())c.addView(tx(sub,13,MUTED,false));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,0,0,dp(10));content.addView(c,lp);if(r!=null)c.setOnClickListener(v->r.run());}
    private void workspace(String n,String s){project=n;style=s;base(n,s+"  •  مساحة مشروع مستقلة");card("🎬  الفيديوهات","استيراد وتشغيل وفحص الفيديو الحقيقي",()->videos(n,s));card("🧪  فحص الفيديو","بيانات المصدر + عينات إطارات حقيقية",()->analysisList(n,s));card("🗂  الأرشيف","مواد المشروع ونتائج الفحص",()->archive(n,s));disabled("💬  شات المشروع","موعده في دفعة الشات");disabled("🧠  الذاكرة","موعدها في دفعات الذاكرة");disabled("✨  المؤثرات والانتقالات","موعد المكتبة في دفعتها");back("رجوع للرئيسية",this::home);}
    private void disabled(String a,String b){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setBackground(bg(Color.rgb(15,18,23),18));c.setPadding(dp(18),dp(13),dp(18),dp(13));c.setAlpha(.6f);c.addView(tx(a,17,Color.WHITE,true));c.addView(tx(b,13,MUTED,false));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,0,0,dp(10));content.addView(c,lp);}

    private String key(String n,String s){return "videos_"+Integer.toHexString((n+"|"+s).hashCode());}
    private JSONArray list(String n,String s){try{return new JSONArray(prefs.getString(key(n,s),"[]"));}catch(Exception e){return new JSONArray();}}
    private void save(String n,String s,JSONArray a){prefs.edit().putString(key(n,s),a.toString()).apply();}
    private void videos(String n,String s){project=n;style=s;base("فيديوهات المشروع",n+"  •  "+s);Button add=btn("＋  استيراد فيديو من الجوال");content.addView(add,new LinearLayout.LayoutParams(-1,dp(58)));add.setOnClickListener(v->pick());TextView note=tx("عند الاستيراد نحفظ صلاحية الملف ونفحص بيانات الفيديو وعينات من إطاراته محليًا على جهازك.",13,MUTED,false);LinearLayout.LayoutParams nl=new LinearLayout.LayoutParams(-1,-2);nl.setMargins(0,dp(12),0,dp(18));content.addView(note,nl);JSONArray a=list(n,s);if(a.length()==0)content.addView(tx("لا توجد فيديوهات حتى الآن.",14,MUTED,false));else for(int i=a.length()-1;i>=0;i--){JSONObject o=a.optJSONObject(i);if(o!=null)videoCard(o,n,s);}back("رجوع للمشروع",()->workspace(n,s));}
    private void videoCard(JSONObject o,String n,String s){String name=o.optString("name","فيديو"),uri=o.optString("uri","");JSONObject in=o.optJSONObject("inspection");String status=in==null?"لم يتم الفحص":"تم الفحص • "+in.optInt("width")+"×"+in.optInt("height")+" • "+in.optJSONArray("samples").length()+" عينات";LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setBackground(bg(CARD,18));c.setPadding(dp(16),dp(13),dp(16),dp(13));c.addView(tx("🎞  "+name,16,Color.WHITE,true));c.addView(tx(status,12.5f,in==null?MUTED:GREEN,true));c.setOnClickListener(v->player(name,uri,n,s));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,0,0,dp(10));content.addView(c,lp);}
    private void analysisList(String n,String s){base("فحص الفيديو",n+"  •  بيانات حقيقية من ملفات المشروع");JSONArray a=list(n,s);if(a.length()==0)content.addView(tx("أضف فيديو أولًا من قسم الفيديوهات.",14,MUTED,false));for(int i=a.length()-1;i>=0;i--){JSONObject o=a.optJSONObject(i);if(o==null)continue;JSONObject in=o.optJSONObject("inspection");card(o.optString("name","فيديو"),in==null?"لم يُفحص بعد":"افتح نتيجة الفحص",in==null?null:()->analysisDetail(o,n,s));}back("رجوع للمشروع",()->workspace(n,s));}
    private void analysisDetail(JSONObject o,String n,String s){JSONObject x=o.optJSONObject("inspection");base("نتيجة الفحص",o.optString("name","فيديو"));if(x==null){content.addView(tx("لا توجد نتيجة.",14,MUTED,false));back("رجوع",()->analysisList(n,s));return;}long ms=x.optLong("durationMs");String info="المدة: "+format(ms)+"\nالأبعاد: "+x.optInt("width")+" × "+x.optInt("height")+"\nالدوران: "+x.optInt("rotation")+"°\nBitrate: "+x.optLong("bitrate")+" bps\nMIME: "+x.optString("mime","—")+"\nFPS المصدر: "+(x.optString("fps","").isEmpty()?"غير متاح من الملف":x.optString("fps"))+"\nصوت: "+(x.optBoolean("hasAudio")?"نعم":"لا");TextView box=tx(info,15,Color.WHITE,false);box.setBackground(bg(CARD,18));box.setPadding(dp(18),dp(15),dp(18),dp(15));content.addView(box);JSONArray sm=x.optJSONArray("samples");TextView h=tx("عينات الإطارات  •  "+(sm==null?0:sm.length()),17,Color.WHITE,true);LinearLayout.LayoutParams hl=new LinearLayout.LayoutParams(-1,-2);hl.setMargins(0,dp(22),0,dp(10));content.addView(h,hl);if(sm!=null)for(int i=0;i<sm.length();i++){JSONObject q=sm.optJSONObject(i);if(q!=null)card(format(q.optLong("timeMs")),"سطوع "+q.optInt("brightness")+"/255  •  نطاق لوني "+q.optInt("colorRange")+"/255",null);}TextView note=tx("هذه قياسات مستخرجة فعليًا من الفيديو. لم نسمّها مشاهد أو انتقالات لأن فهم القصّات والحركة يأتي في الدفعة التالية.",13,MUTED,false);content.addView(note);back("رجوع للفحص",()->analysisList(n,s));}
    private void archive(String n,String s){base("أرشيف المشروع","الفيديوهات ونتائج الفحص المحفوظة داخل "+n);JSONArray a=list(n,s);if(a.length()==0)content.addView(tx("الأرشيف فارغ.",14,MUTED,false));else for(int i=a.length()-1;i>=0;i--){JSONObject o=a.optJSONObject(i);if(o!=null)videoCard(o,n,s);}back("رجوع للمشروع",()->workspace(n,s));}

    private void pick(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("video/*");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(i,PICK_VIDEO);}
    @Override protected void onActivityResult(int rc,int result,Intent data){super.onActivityResult(rc,result,data);if(rc!=PICK_VIDEO||result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}JSONArray a=list(project,style);for(int i=0;i<a.length();i++){JSONObject old=a.optJSONObject(i);if(old!=null&&uri.toString().equals(old.optString("uri"))){Toast.makeText(this,"الفيديو موجود بالفعل",Toast.LENGTH_SHORT).show();videos(project,style);return;}}JSONObject o=new JSONObject();try{o.put("name",displayName(uri));o.put("uri",uri.toString());o.put("added",System.currentTimeMillis());Toast.makeText(this,"جارٍ فحص الفيديو…",Toast.LENGTH_SHORT).show();o.put("inspection",VideoInspector.inspect(this,uri));a.put(o);save(project,style,a);Toast.makeText(this,"تمت الإضافة والفحص بنجاح",Toast.LENGTH_SHORT).show();}catch(Exception e){try{a.put(o);save(project,style,a);}catch(Exception ignored){}Toast.makeText(this,"تمت الإضافة لكن تعذر فحص هذا الملف",Toast.LENGTH_LONG).show();}videos(project,style);}
    private String displayName(Uri u){Cursor c=null;try{c=getContentResolver().query(u,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null);if(c!=null&&c.moveToFirst()){int x=c.getColumnIndex(OpenableColumns.DISPLAY_NAME);if(x>=0)return c.getString(x);}}catch(Exception ignored){}finally{if(c!=null)c.close();}return "فيديو";}
    private String format(long ms){long t=ms/1000,h=t/3600,m=(t%3600)/60,s=t%60;return h>0?String.format(Locale.US,"%d:%02d:%02d",h,m,s):String.format(Locale.US,"%02d:%02d",m,s);}
    private void player(String file,String uri,String n,String s){base("مشغل الفيديو",file);FrameLayout f=new FrameLayout(this);f.setBackgroundColor(Color.BLACK);VideoView vv=new VideoView(this);f.addView(vv,new FrameLayout.LayoutParams(-1,dp(230)));content.addView(f,new LinearLayout.LayoutParams(-1,dp(238)));MediaController mc=new MediaController(this);mc.setAnchorView(vv);vv.setMediaController(mc);vv.setVideoURI(Uri.parse(uri));vv.setOnPreparedListener(mp->vv.start());vv.setOnErrorListener((mp,w,e)->{Toast.makeText(this,"تعذر تشغيل الملف",Toast.LENGTH_LONG).show();return true;});back("رجوع للفيديوهات",()->videos(n,s));}
    @Override public void onBackPressed(){if(backAction!=null)backAction.run();else home();}
}
